// Create lifted points for the four vertices of the cell
  LiftedPoint p[4];
  for (int i = 0; i < 4; ++i) {
    auto const &pt = c->vertex(i)->point();
    p[i] = lifted_point(
      pt.x(), pt.y(), pt.z(), pt.weight());
  }

  // Create hyperplane in 4D from the four lifted points
  HyperPlane h(4, p, p + 4);

  // Extract velocity components from hyperplane coefficients
  double a = CGAL::to_double(h.orthogonal_vector()[0]);
  double b = CGAL::to_double(h.orthogonal_vector()[1]);
  double c_coeff = CGAL::to_double(h.orthogonal_vector()[2]);
  double d = CGAL::to_double(h.orthogonal_vector()[3]);

  // The velocity is derived from the normal vector of the hyperplane
  // In the context of the adhesion model, the velocity is related to the gradient of the hyperplane
  // defined by the lifted points in 4D. The velocity vector (a,b,c) represents the gradient of the plane
  // in 3D space, and we normalize by the time component 'd' (assuming d != 0)
  if (d == 0) {
    return Vector(infinity, infinity, infinity);
  } else {
    return Vector(a / -d, b / -d, c_coeff / -d);
  }

